arguments.command:
cat > /tmp/joey-cred.sh <<'EOF'
#!/bin/sh
case "$1" in
  get) echo "username=x-access-token"; echo "password=${GITHUB_TOKEN}";;
  store|erase) : ;;
esac
EOF
chmod +x /tmp/joey-cred.sh
git -C /tmp/friends-conv/joey -c user.name='github-actions[bot]' -c user.email='41898282+github-actions[bot]@users.noreply.github.com' commit --allow-empty -F /tmp/joey-msg.txt 2>&1 | tail -3
